impl Solution{pub fn max_number(a:Vec<i32>,b:Vec<i32>,k:i32)->Vec<i32>{fn pick(a:&[i32],k:usize)->Vec<i32>{let mut s=vec![];let mut drop=a.len()-k;for &x in a{while drop>0&&!s.is_empty()&&*s.last().unwrap()<x{s.pop();drop-=1}s.push(x)}s.truncate(k);s}fn ge(a:&[i32],mut i:usize,b:&[i32],mut j:usize)->bool{while i<a.len()&&j<b.len()&&a[i]==b[j]{i+=1;j+=1}j==b.len()||(i<a.len()&&a[i]>b[j])}fn merge(a:Vec<i32>,b:Vec<i32>)->Vec<i32>{let(mut i,mut j)=(0,0);let mut r=vec![];while i<a.len()||j<b.len(){if ge(&a,i,&b,j){r.push(a[i]);i+=1}else{r.push(b[j]);j+=1}}r}let k=k as usize;let mut best=vec![];let lo=k.saturating_sub(b.len());let hi=k.min(a.len());for i in lo..=hi{let r=merge(pick(&a,i),pick(&b,k-i));if r>best{best=r}}best}}
